-- ============================================================================
-- D2 EXPERT DEEP SEED: Machine Learning on Well Data, advanced tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, and the question rows from the
-- committed bank JSONs under tools/course-banks/mlcore/advanced.
--
-- What this tier owns: WHEN THE ENGINE REFUSES, STOPS OR EXTRAPOLATES. The
-- condition number raw and scaled, the refusal limit and the NIST reference
-- problems (Longley, Filip refused, what a digit means); complete and
-- quasi-complete separation and the exact test before any iteration; Newton
-- steps, the stopping rule in coefficient units, step halving and a fit that
-- stops early; permutation importance with its seed and repeats, and the
-- learning curve counted in wells; a missing log predicted, range checked and
-- written back; conventions that are choices. Digest sections 17 to 25, and
-- section 26.
--
-- THE TRAP THE TIER IS BUILT ON. A number the engine returns is only as good as
-- the rule it states: a refusal declines digits nobody can vouch for, a warning
-- says the fit stopped early, and a range check sees only the rows that leave
-- the range. The Expert capstone grades six Expert quantities.
-- ============================================================================

values ('mlcore', 'advanced', '{"modules":[{"key":"m01-conditioning-and-nist","title":"Conditioning and the NIST Reference Problems","lesson_keys":["l01-the-condition-number","l02-the-refusal-limit","l03-longley-and-the-certified-values","l04-filip-refused","l05-what-digits-mean"]},{"key":"m02-separation","title":"Separation","lesson_keys":["l01-complete-separation","l02-quasi-complete-separation","l03-the-exact-test","l04-a-penalty-that-fits"]},{"key":"m03-convergence","title":"Convergence and Its Stated Rule","lesson_keys":["l01-newton-steps-from-zero","l02-the-stopping-rule","l03-step-halving","l04-when-a-fit-does-not-converge"]},{"key":"m04-importance-and-learning-curves","title":"Importance and Learning Curves","lesson_keys":["l01-permutation-importance","l02-a-feature-that-carries-nothing","l03-repeats-and-their-spread","l04-the-learning-curve-in-wells","l05-reading-a-learning-curve"]},{"key":"m05-missing-log-prediction","title":"Missing-Log Prediction End to End","lesson_keys":["l01-the-well-with-no-sonic","l02-choosing-features-by-wells","l03-a-well-outside-the-training-range","l04-writing-a-prediction-back"]},{"key":"m06-reading-the-engine-honestly","title":"Reading the Engine Honestly","lesson_keys":["l01-conventions-that-are-choices","l02-what-is-not-built","l03-writing-the-model-note","l04-the-capstone-brief"]}]}'::jsonb, 1)
